mapper.select:
select id, conversation_id, member_id, role, unread_count, last_read_msg_id, muted, deleted, create_time
from im_conversation_member
where conversation_id = #{conversationId}

mapper.update:
update im_conversation_member
set unread_count = 0, last_read_msg_id = #{lastReadMsgId}
where conversation_id = #{conversationId} and member_id = #{memberId}
